"""Pure preparation with generated bytes and a mocked candidate qualification."""
import json
from pathlib import Path
import subprocess
import tempfile
from types import SimpleNamespace
import unittest
from unittest.mock import patch

import compare_memory as runner
from history_export_build import SOURCES
from memory_public_history import VISUAL_MEMORY_SCOPE, VISUAL_MEMORY_TRANSPORT


class MemoryPhasePreparationTests(unittest.TestCase):
    def test_shared_qualified_alias_implementation_is_an_explicit_preparation_pin(self):
        import compare_history
        import history_executable_identity
        self.assertIs(compare_history.same_executable_file,history_executable_identity.same_executable_file)
        self.assertIn('history_executable_identity.py',compare_history.RUNTIME)
        self.assertIn('history_executable_identity.py',compare_history.LAUNCH_TOOLING)

    def test_default_and_optin_freeze_exact_separate_inventory_and_same_samples(self):
        with tempfile.TemporaryDirectory(dir='/private/tmp') as name:
            root=Path(name);candidate=root/'candidate';candidate.mkdir()
            (candidate/'candidate.json').write_text('{"purpose":"synthetic-test-only"}')
            cmdy=candidate/'cmdy';cmdy.write_bytes(b'generated-unexecuted-cmdy')
            ghostty=root/'ghostty';ghostty.write_bytes(b'generated-unexecuted-comparator')
            q=dict(binary='cmdy',signed_binary_sha256=runner.coordinator.sha(cmdy))
            helpers={}
            for key in ('window_helper','memory_helper','history_helper'):
                path=root/key;path.write_bytes(('unexecuted-'+key).encode());helpers[key]=path
            memory=root/'memory-qualification.json'
            memory.write_text(json.dumps(dict(status='pass',ownedProcessReaped=True,sourceUnchanged=True,
                sourceSHA256=runner.coordinator.sha(runner.coordinator.TESTS/'TerminalMemorySnapshot.c'),
                binarySHA256=runner.coordinator.sha(helpers['memory_helper']))))
            native=root/'history-build.json'
            native.write_text(json.dumps(dict(status='pass',reaped=True,sourcesUnchanged=True,
                binarySHA256=runner.coordinator.sha(helpers['history_helper']),
                sourceSHA256={name:runner.coordinator.sha(runner.coordinator.TESTS/name) for name in SOURCES})))
            plans=[]
            with patch.object(runner.coordinator.candidate_preparation,'verify',return_value=q), \
                    patch.object(subprocess,'Popen',side_effect=AssertionError('prepare cannot execute a process')):
                for selected in (False,True):
                    args=SimpleNamespace(candidate=candidate,output=root/('phase' if selected else 'legacy'),
                        ghostty_bin=ghostty,ghostty_sha256=runner.coordinator.sha(ghostty),profile='matched',
                        power_source='AC Power',display_id=1,memory_qualification=memory,history_build=native,
                        post_sample_history=selected,**helpers)
                    runner.prepare(args);plan=runner.coordinator.read(args.output/'plan.json');plans.append(plan)
                    case=plan['cases'][0]
                    self.assertEqual(plan['schemaVersion'],2 if selected else 1)
                    self.assertEqual(case['command'].count('--post-sample-history'),int(selected))
                    self.assertEqual(case.get('postSampleHistory'),True if selected else None)
                    self.assertEqual((args.output/'tooling/Tests/history_executable_identity.py').exists(),selected)
                    self.assertEqual(plan['measuredSamples'],216);self.assertEqual(plan['nativeLaunches'],36)
                    self.assertEqual(plan['minimumHumanIdleSeconds'],300);self.assertEqual(plan['maximumCaseSeconds'],1800)
                    self.assertFalse((args.output/'memory').exists())
                    if selected:
                        self.assertEqual(plan['historyTransport'],VISUAL_MEMORY_TRANSPORT)
                        self.assertEqual(plan['verificationScope'],VISUAL_MEMORY_SCOPE);self.assertEqual(plan['childUmask'],63)
                    else:self.assertNotIn('childUmask',plan);self.assertNotIn('verificationScope',plan)
                self.assertEqual(plans[0]['policySHA256'],plans[1]['policySHA256'])

    def test_audit_refuses_unjoined_optin_before_reading_any_run(self):
        with patch.object(runner.coordinator,'read',side_effect=AssertionError('no run should be read')):
            for case in (dict(output='/generated',postSampleHistory=True,command=[]),
                         dict(output='/generated',command=['--post-sample-history'])):
                with self.assertRaisesRegex(RuntimeError,'explicit case mode'):
                    runner.audit_case(case)


if __name__=='__main__':unittest.main()
